B.aVq=new A.bX([0,"\uc774\ub808\ub97c \ud558\ub8e8\ub3c4 \uc548 \ube60\uc84c\uad6c\uba3c. \ub0b4\uac00 \uc544\uaef4 \ub454 \uac70\uc57c, \ubc1b\uc73c\ub77c\uace0.",3,"\uc77c\uc8fc\uc77c \ub0b4\ub0b4 \ud588\uc5b4\uc694! \uc774\uac70 \uc120\ubb3c\uc774\uc5d0\uc694. \uc81c\uac00 \uc81c\uc77c \uba3c\uc800 \ucc3e\uc558\uc5b4\uc694.",4,"\uc774\ub808 \ub3d9\uc548 \uc695\ubd24\ub370\uc774. \uc774\uac70 \ubc1b\uc544\ub77c, \uadc0\ud55c \uae30\ub2e4.",5,"\uc77c\uc8fc\uc77c \uac1c\uadfc\uc774\ub124. \uc0c1 \uc918\uc57c\uc9c0. \uc774\uac70 \uac00\uc838\uac00.",6,"\uce60 \uc77c \uc5f0\uc18d\uc774\uba74 \ud604\uc7a5\uc5d0\uc120 \ud3ec\uc0c1\uac10\uc774\uc57c. \ubc1b\uc544.",10,"\uc77c\uc8fc\uc77c \uac1c\uadfc \ucd95\ud558\ud574\uc694. \uc624\ub298 \ubc29\uc1a1 \uccab \uace1\uc740 \ub2f9\uc2e0 \uac70\uc608\uc694. \uc774\uac74 \uc120\ubb3c\uc774\uace0\uc694.",12,"\uc774\ub808\ub97c \uaf2c\ubc15 \ucc44\uc6e0\uad6c\uba3c. \uc2dc\uac04\uc744 \uc798 \uc4f0\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc8fc\ub294 \uac78\uc138.",17,"\u2026\uce60 \uc77c \ub0b4\ub0b4 \ud588\ub124. \uc774\uac70, \ub108 \uac00\uc838."],t.TM)
