B.aVs=new A.bX([0,"\uc5b4\uc81c\ub294 \uc26c\uc5c8\uad6c\uba3c. \uad1c\ucc2e\uc544, \uc624\ub298\ubd80\ud130 \ub2e4\uc2dc \uc138\uc790\uace0.",3,"\uc5b4\uc81c \uc548 \uc654\uc8e0? \uad1c\ucc2e\uc544\uc694, \uc624\ub298\ubd80\ud130 \ub2e4\uc2dc \uc138\uc5b4\uc694!",4,"\uc5b4\uc81c\ub294 \uc26c\uc5c8\ub098. \uad1c\ucc2e\ub2e4, \uc26c\ub294 \ub0a0\ub3c4 \uc788\uc5b4\uc57c\uc81c.",5,"\uc5b4\uc81c \ube7c\uba39\uc5c8\uc9c0? \ub410\uc5b4, \uc624\ub298 \ub2e4\uc2dc \ud558\uba74 \ub3fc.",6,"\ud558\ub8e8 \ube60\uc84c\ub124. \uad1c\ucc2e\uc544, \ub2e4\uc2dc \uc313\uc73c\uba74 \ub3fc.",10,"\uc5b4\uc81c\ub294 \uc26c\uc5b4 \uac00\ub294 \ub0a0\uc774\uc5c8\ub124\uc694. \uc624\ub298 \ub2e4\uc2dc \uc2dc\uc791\ud574\uc694.",12,"\ud558\ub8e8 \uc26c\uc5c8\uad6c\uba3c. \ud0dc\uc5fd\uc740 \ub2e4\uc2dc \uac10\uc73c\uba74 \ub418\ub294 \uac78\uc138.",17,"\u2026\uc5b4\uc81c \uc548 \uc654\ub354\ub77c. \ubb50, \uad1c\ucc2e\uc544."],t.TM)
