B.b_2=new A.b(B.b4q,["\ubd88 \uc880 \ub354 \ucb10\uace0 \uac00\uac70\ub798\uc774.","\uc624\ub298\ub3c4 \ubb34\uc0ac\ud788 \ub118\uacbc\ub370\uc774.","\ubcc4\uc774 \ud558\ub098 \ub5b4\ub370\uc774.","\ub0b4\uc77c\uc740 \ubb58 \uc2ec\uc5b4 \ubcfc\uaf2c.","\ud654\ubd84\uc5d0 \uc0c8 \uc78e\uc774 \ub0ac\ub370\uc774.","\ubb3c \uc8fc\ub294 \uac70 \uc78a\uc9c0 \ub9c8\ub798\uc774.","\uae43\ubc1c\uc774 \uc800\uc9dd\uc73c\ub85c \ud384\ub7ed\uc778\ub370\uc774.","\uba40\ub9ac\uc11c\ub3c4 \ubcf4\uc774\uaca0\ub370\uc774.","\uc758\uc790 \ud558\ub098 \uc0dd\uae30\ub2c8 \uc0b4 \uac83 \uac19\ub370\uc774.","\ucabc\ub9e4 \uc549\uc558\ub2e4 \uac00\uaed8.","\uac00\ub85c\ub4f1 \ubc11\uc774 \uc824 \ub530\uc229\ub2e4.","\ubc24\uc774 \ub35c \ubb34\uc12d\ub370\uc774.","\ud48d\uacbd \uc18c\ub9ac \ub4e4\ub9ac\ub098?","\ubc14\ub78c\uc774 \ubc14\ub00c\uc5c8\ub370\uc774.","\ubd88\ube5b \uc904 \uc544\ub798 \ubaa8\uc774\ub798\uc774.","\ubc24\uc774 \uc794\uce58 \uac19\ub370\uc774.","\ubcbd\ud654 \uc55e\uc5d0\uc11c \uc0ac\uc9c4 \ud55c \uc7a5 \ubc15\uace0 \uc2f6\ub370\uc774.","\ub204\uac00 \uadf8\ub838\ub294\uc9c0 \uc54c\uaca0\ub370\uc774.","\uc5ec \uc11c\uba74 \ub9c8\uc74c\uc774 \uac00\ub77c\uc549\ub294\ub2e4.","\uc78a\uc9c0 \ub9d0\uc790\ub294 \uae30\uc81c, \uc774\uae30.","\ub9dd\uce58 \uc18c\ub9ac \ub4e3\uae30 \uc88b\uc81c?","\ucca0\ud310 \ud55c \uc7a5 \ub354 \ub098\uc624\uaca0\ub370\uc774.","\ud759\uc774 \ub2e4\uc2dc \ubcf4\ub4dc\ub77c\uc6cc\uc84c\ub370\uc774.","\uac10\uc790 \uc2f9\uc774 \ub0ac\ub370\uc774!","\ube57\ubb3c\uc774 \ub9d1\uac8c \uac78\ub7ec\uc9c4\ub370\uc774.","\ubb3c \uac71\uc815\uc740 \ub35c\uc5c8\ub2e4.","\uc0c1\uc790\ub9c8\ub2e4 \uc774\ub984\ud45c \ubd99\uc5ec \ub1a8\ub370\uc774.","\ucc3d\uace0\uac00 \ub4e0\ub4e0\ud558\ub370\uc774.","\uae30\ub984\ub9cc \uc788\uc73c\ubaa8 \ubc24\uc0c8 \ub3cc\uc544\uac04\ub370\uc774.","\uc804\uad6c\uac00 \ub2e4\uc2dc \ucf1c\uc84c\ub370\uc774!","\uc5b4\ub370 \ub2e4\uce5c \ub370\ub294 \uc5c6\ub098?","\ubd95\ub300\ub294 \ub109\ub109\ud558\ub370\uc774.","\uc7a1\uc74c \uc18d\uc5d0 \ub204\uac00 \ubd80\ub974\ub294 \uac70 \uac19\ub370\uc774.","\uc624\ub298\ub3c4 \uc2e0\ud638\ub97c \uae30\ub2e4\ub824 \ubcf8\ub370\uc774.","\ubd88 \uc548 \uaebc\uc9c0\uac8c \ub0b4\uac00 \uc9c0\ud0a4\uafb8\ub9c8.","\uba40\ub9ac\uae4c\uc9c0 \ube5b\uc774 \ub2ff\ub294\ub370\uc774.","\uc774 \uace0\ucca0 \ub354\ubbf8\uac00 \ub2e4 \ubcf4\ubb3c\uc774\ub370\uc774.","\uc4f8 \ub9cc\ud55c \uae30 \ub610 \ub098\uc654\ub370\uc774!"],t.w)
