B.aJ1=s(["\uc6d0\uc815 \ud0ed \ub9e8 \uc704 \u2018\uc9c0\ud558 \uad6c\uc5ed\u2019\uc5d0\uc11c \u2018\ub0b4\ub824\uac08 \uc900\ube44\u2019\ub97c \ub20c\ub7ec\uc694.","\ucd5c\ub300 3\uba85\uacfc \uc5f0\ub8cc\ub97c \ucc59\uaca8\uc694. \uc5f0\ub8cc 1\uac1c\ub294 \uae30\ub984 3\uc774\uc5d0\uc694.","\uc5b4\ub450\uc6b4 \uce78\uc744 \ud55c \ubc88 \ub450\ub4dc\ub9b4 \ub54c\ub9c8\ub2e4 \uae30\ub984 1\uc744 \uc368\uc694. \uacc4\ub2e8\uc744 \ucc3e\uc544 \ub354 \uae4a\uc774 \ub0b4\ub824\uac00\uc694.","\uae30\ub984\uc774 \ub5a8\uc5b4\uc9c0\uae30 \uc804\uc5d0 \uc62c\ub77c\uc640\uc694. \ub5a8\uc5b4\uc9c0\uba74 \ucc59\uae34 \uac83\uc758 \uc808\ubc18\uc744 \uc783\uc5b4\uc694."],t.s)
B.a3n=new A.fd("u:stairs","\ub79c\ud134 \uae30\ub984\uc774 \ubc84\ud2f0\ub294 \ub9cc\ud07c \uc9c0\ud558\ub85c \ub0b4\ub824\uac00 \uadc0\ud55c \ubb3c\uc790\uc640 \uc0ac\ub78c\ub4e4\uc758 \uae30\ub85d\uc744 \ucc3e\uc544\uc694.",B.aJ1,"\ub2e4\uc74c \ud0d0\uc0ac\ub294 \uc9c0\ub09c\ubc88 \uba48\ucd98 \uce35\ubd80\ud130 \uc2dc\uc791\ud574\uc694. 1\uce35\ubd80\ud130 \ub2e4\uc2dc \ub0b4\ub824\uac08 \uc218\ub3c4 \uc788\uc5b4\uc694.")
B.axt=s(["\uc77c\uc9c0\uc5d0\uc11c \u2018\ub3c4\uac10\u2019 \ud0ed\uc744 \ub20c\ub7ec\uc694.","\ucc3e\uc740 \uc720\ubb3c\uc758 \uc774\uc57c\uae30\uc640 \ud6a8\uacfc\ub97c \ubcfc \uc218 \uc788\uc5b4\uc694.","\uc720\ubb3c\uc740 \uc774\uc8fc\ud560 \ub54c\ub3c4 \ud568\uaed8 \uac00\uc838\uac00\uc694."],t.s)
